public sealed class FeeCalculator(IEnumerable<IFeePolicy> policies)
{
    private readonly Dictionary<string, IFeePolicy> _byType = policies.ToDictionary(p => p.Type);
    public decimal Fee(Payment p) => _byType.TryGetValue(p.Type, out var policy)
        ? policy.Fee(p.Amount) : throw new NotSupportedException(p.Type);
}
